select t.* from (
    select i.*, case when i.status = 0 and i.invite_type != 2
        and ((i.expire_time is not null and i.expire_time <= #{now})
          or (i.create_time is not null and i.create_time <= DATE_SUB(#{now}, INTERVAL 48 HOUR)))
        then 5 else i.status end as effective_status
    from coop_invite i where i.del_flag = 0
) t

     and t.invite_type = #{query.inviteType}
     and t.from_type = #{query.fromType}
     and t.from_id = #{query.fromId}
     and t.to_type = #{query.toType}
     and t.to_id = #{query.toId}
     and t.topic_id = #{query.topicId}
     and t.game_id = #{query.gameId}
     and t.effective_status = #{query.status}

order by t.create_time desc

