update coop_invite
set status = 5, update_time = #{now}
where topic_id = #{topicId} and del_flag = 0 and status = 0 and invite_type != 2

update coop_invite set deposit_status=#{status},deposit_amount=#{amount},update_time=now()
where id=#{id} and invite_type != 2 and del_flag=0 and deposit_status <=> #{expectedStatus}
  and deposit_amount <=> #{expectedAmount} and deposit_refund_state is null

